def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    for _, opp in history:
        if opp == 'D':
            opp_def += 1

    if opp_def == 0:
        if n <= 1:
            return 'C'
        if n == 2:
            return 'D'
        if n == 3:
            return 'C'
        return 'D'

    start = n - 2
    if start < 0:
        start = 0
    for i in range(start, n):
        my, opp = history[i]
        if my == 'D' and opp == 'C':
            return 'C'

    last_opp = history[-1][1]
    if last_opp == 'C':
        return 'C'
    else:
        return 'D'
